    (error as { code?: string }).code === "ENOENT"
  );
}

async function searchWithRg(opts: {
  cwd: string;
  pattern: string;
  root: string;
  glob?: string;
}): Promise<Hit[]> {
  const workspace = realpathSync(opts.cwd);
  let relRoot = path.relative(workspace, opts.root);
  if (relRoot === "") relRoot = ".";
  const args = [
    "-n",
    "-H",
    "--no-heading",
    "--color",
    "never",
    "--glob",
    "!.git/**",
    "--glob",
    "!.sage/**",
    "--glob",
    "!node_modules/**",
    "-e",
    opts.pattern,
  ];
  if (opts.glob) args.push("--glob", opts.glob);
  args.push(relRoot);
  const output = await runRg(args, workspace);
  const hits: Hit[] = [];
  for (const raw of output.split("\n")) {
    if (raw.length === 0) continue;
    const match = /^([^:]+):(\d+):(.*)$/.exec(raw);
    if (!match) continue;
    const file = (match[1] ?? "")
      .replace(/^\.\//, "")
      .split(path.sep)
      .join("/");
    const line = Number(match[2]);
    const text = match[3] ?? "";
    if (!Number.isInteger(line)) continue;
    hits.push({ file, line, text });
  }
  return hits;
}

function runRg(args: string[], cwd: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const child = spawn("rg", args, { cwd });
    const stdout: Buffer[] = [];
    const stderr: Buffer[] = [];
    child.stdout?.on("data", (chunk: Buffer) => stdout.push(chunk));
    child.stderr?.on("data", (chunk: Buffer) => stderr.push(chunk));
    child.on("error", reject);
    child.on("close", (code) => {
      if (code === 0 || code === 1) {
        resolve(Buffer.concat(stdout).toString("utf8"));
        return;
      }
      reject(
        new Error(
          Buffer.concat(stderr).toString("utf8") || `rg exited ${code}`,
        ),
      );
    });
  });
}

